@startuml

class SensorController {
  + address : string
}

class Apartment {
  + address : string
  + inhabitants : int
}

class User {
  + username : string
  + password : string
  + isAdmin : boolean
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : string
  + room : Room
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + counterReading : long
}

class Threshold {
  + value : float
  + email : string
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

User "1" -- "*" Apartment
Apartment "1" *-- "* Room"
Room "1" *-- "* Sensor"
Sensor "1" -- "0..*" Threshold
Sensor "1" -- "*" SensorValue

@enduml

